export function getDecksBySubject(): Record<string, LibraryDeck[]> {
  return LIBRARY_DECKS.reduce((acc, d) => {
    (acc[d.subject] ??= []).push(d);
    return acc;
  }, {} as Record<string, LibraryDeck[]>);
}
